import stdx.serialization.serialization.*
class Box <: Serializable<Box> {
 let value: Int64
 init(v: Int64) { value = v }
 public func serialize(): DataModel { DataModelStruct().add(Field("value", value.serialize())) }
 public static func deserialize(dm: DataModel): Box { Box(Int64.deserialize((dm as DataModelStruct).getOrThrow().get("value"))) }
}

